const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8').split(/\s+/);
  let ptr = 0;
  while (ptr < data.length && data[ptr] === '') ptr++;

  const V = +data[ptr++], N = +data[ptr++], M = +data[ptr++];

  const deg = new Int32Array(N + 2);
  const ea = new Int32Array(M), eb = new Int32Array(M);
  const et = new Int32Array(M), ep = new Int32Array(M);
  for (let i = 0; i < M; i++) {
    ea[i] = +data[ptr++]; eb[i] = +data[ptr++];
    et[i] = +data[ptr++]; ep[i] = +data[ptr++];
    deg[ea[i]]++; deg[eb[i]]++;
  }
  const X = +data[ptr++], Y = +data[ptr++];

  // CSR adjacency
  const start = new Int32Array(N + 2);
  for (let u = 1; u <= N; u++) start[u + 1] = start[u] + deg[u];
  const eV = new Int32Array(2 * M);
  const eT = new Int32Array(2 * M);
  const eP = new Int32Array(2 * M);
  const fill = new Int32Array(N + 2);
  for (let u = 1; u <= N; u++) fill[u] = start[u];
  for (let i = 0; i < M; i++) {
    let j = fill[ea[i]]++;
    eV[j] = eb[i]; eT[j] = et[i]; eP[j] = ep[i];
    j = fill[eb[i]]++;
    eV[j] = ea[i]; eT[j] = et[i]; eP[j] = ep[i];
  }

  // Dijkstra over states (node, cost spent), minimizing time
  const S = V + 1;
  const dist = new Float64Array((N + 1) * S);
  dist.fill(Infinity);

  const CAP = 1 << 20; // pushes <= 1 + (V+1)*2M
  const hId = new Int32Array(CAP);
  const hK = new Float64Array(CAP);
  let hn = 0;

  const s0 = X * S; // state (X, cost 0)
  dist[s0] = 0;
  hId[0] = s0; hK[0] = 0; hn = 1;

  let ans = -1;

  while (hn > 0) {
    // pop min
    const topId = hId[0], topK = hK[0];
    hn--;
    if (hn > 0) {
      const lastId = hId[hn], lastK = hK[hn];
      let hole = 0;
      for (;;) {
        let child = 2 * hole + 1;
        if (child >= hn) break;
        if (child + 1 < hn && hK[child + 1] < hK[child]) child++;
        if (hK[child] >= lastK) break;
        hId[hole] = hId[child]; hK[hole] = hK[child];
        hole = child;
      }
      hId[hole] = lastId; hK[hole] = lastK;
    }

    if (topK > dist[topId]) continue; // stale entry

    const u = (topId / S) | 0;
    if (u === Y) { ans = topK; break; }
    const cost = topId - u * S;
    const j0 = start[u], j1 = start[u + 1];
    for (let j = j0; j < j1; j++) {
      const nc = cost + eP[j];
      if (nc > V) continue;
      const nid = eV[j] * S + nc;
      const nd = topK + eT[j];
      if (nd < dist[nid]) {
        dist[nid] = nd;
        // push (nid, nd)
        let hole = hn++;
        while (hole > 0) {
          const parent = (hole - 1) >> 1;
          if (hK[parent] <= nd) break;
          hId[hole] = hId[parent]; hK[hole] = hK[parent];
          hole = parent;
        }
        hId[hole] = nid; hK[hole] = nd;
      }
    }
  }

  process.stdout.write(ans + '\n');
}

main();
